export const fieldById = Object.fromEntries(fields.map((f) => [f.id, f]));
export const fieldRange = (prefix, start, end) =>
  Array.from(
    { length: end - start + 1 },
    (_, i) => prefix + String(start + i).padStart(2, "0")
  );
